package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaViDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rooster_donkey" to DuaText("Nghe thấy tiếng gà trống hoặc con lừa", "Ôi Allah, tôi yêu cầu bạn về tiền thưởng của bạn (gà trống). — Tôi cầu xin Allah che chở khỏi Shaytan, kẻ đáng nguyền rủa (con lừa).", "Khi nghe tiếng gà trống cầu xin tiền thưởng của Allah; khi nghe tiếng lừa kêu tìm nơi ẩn náu khỏi Shaytan.", "Con gà trống nhìn thấy thiên thần và con lừa nhìn thấy ác quỷ."),
        "dua_something_liked" to DuaText("Nhìn thấy điều gì đó đáng ngưỡng mộ (Chống lại mắt ác)", "Những gì Allah đã mong muốn. Ôi Allah, ban phước cho nó.", "Khi nhìn thấy điều gì đó đáng ngưỡng mộ của ai đó, hãy cầu nguyện để được ban phước lành.", "Cầu nguyện phước lành ngăn ngừa mắt ác."),
        "dua_sell_buy_debt_repaid" to DuaText("Khi trả nợ", "Có thể Allah ban phước lành cho bạn trong gia đình và sự giàu có của bạn.", "Đối với người cho vay khi trả nợ.", "Sự trả lại của một khoản vay là cảm ơn và trả nợ."),
        "dua_talbiyah" to DuaText("Talbiyah", "Tôi đây, ôi Allah, tôi đây. Tôi đây, Bạn không có đối tác, tôi đây. Chắc chắn mọi lời khen ngợi, phước lành và quyền thống trị đều thuộc về Ngài. Bạn không có đối tác.", "Lớn tiếng sau khi vào ihram.", "Biểu tượng của Hajj và Umrah."),
        "dua_yamani_hajar" to DuaText("Giữa Rukn Yamani và Hajar Aswad", "Lạy Chúa, xin ban cho chúng con điều tốt lành ở đời này và điều tốt lành ở Đời sau, và bảo vệ chúng con khỏi sự trừng phạt của Lửa.", "Ở tawaf, giữa Góc Yemen và Đá Đen.", "Nhà tiên tri ﷺ đã đọc điều này tại nơi này ở tawaf."),
        "dua_safa_marwa" to DuaText("Trên Safa và Marwah", "Không ai có quyền được tôn thờ ngoại trừ Allah, một mình, không có đối tác. Ngài là quyền thống trị và Ngài là sự ca ngợi, và Ngài có quyền trên mọi sự. Không ai có quyền được tôn thờ ngoại trừ Allah; Ngài đã thực hiện lời hứa của mình, giúp đỡ đầy tớ của Ngài và một mình đánh bại quân miền Nam.", "Leo lên Safa và đối mặt với Qiblah (ba lần).", "Các dhikr của Nhà tiên tri ﷺ trên Safa và Marwah."),
        "dua_arafah" to DuaText("Dua hay nhất trong ngày của Arafah", "Không ai có quyền được tôn thờ ngoại trừ Allah, một mình, không có đối tác. Ngài là quyền thống trị và Ngài là sự ca ngợi, và Ngài có quyền trên mọi sự.", "Ngày của Arafah — bản dua hay nhất.", "Dua hay nhất là dua của Ngày Arafah, và những lời hay nhất là đây."),
        "dua_takbeer_tashreeq" to DuaText("Takbeer-e-Tashreeq", "Allah là Đấng vĩ đại nhất, Allah là Đấng vĩ đại nhất. Không có thần nào ngoài Allah. Allah là Đấng vĩ đại nhất, Allah là Đấng vĩ đại nhất và mọi lời khen ngợi đều dành cho Allah.", "Sau mỗi lời cầu nguyện bắt buộc từ Fajr của 9 Dhul-Hijjah đến Asr của 13 Dhul-Hijjah.", "Báo cáo từ Ali và Ibn Mas'ud (RA) — wajib theo Hanafis."),
        "dua_zamzam" to DuaText("Uống Zamzam", "Ôi Allah, tôi cầu xin Ngài ban cho những kiến ​​thức hữu ích, nguồn cung cấp dồi dào và phương pháp chữa khỏi mọi bệnh tật.", "Khi uống Zamzam, hãy pha dua cho bất cứ điều gì bạn dự định.", "Zamzam dành cho bất cứ thứ gì người ta say (Ibn Majah 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("Suy ngẫm về sự sáng tạo", "Lạy Chúa, Chúa đã không tạo ra tất cả những điều này một cách vô ích. Vinh quang thay Ngài, xin hãy bảo vệ chúng con khỏi sự trừng phạt của Lửa.", "Dua của những người suy ngẫm về sự sáng tạo của trời và đất.", "Dua của người hiểu biết (ulul-albab)."),
        "dua_q_sami_na_munadiyan" to DuaText("Chúng tôi đã nghe thấy tiếng gọi của niềm tin", "Lạy Chúa, chúng con đã nghe một người kêu gọi đức tin nói rằng 'Hãy tin vào Chúa của con', và chúng con đã tin. Lạy Chúa, xin tha tội cho chúng con, xóa khỏi chúng con những việc ác và khiến chúng con chết chung với người công chính.", "Một dua cho đức tin và cái chết giữa những người công chính.", "Một dua cho sự tha thứ và một kết thúc tốt đẹp."),
        "dua_q_atina_ma_waadtana" to DuaText("Hãy cho chúng tôi những gì bạn đã hứa", "Lạy Chúa, xin ban cho chúng con những gì Ngài đã hứa với chúng con qua các Sứ giả của Ngài và đừng làm chúng con hổ thẹn vào Ngày Phục Sinh. Quả thật, Ngài không thất hứa.", "Trốn tránh sự ô nhục vào Ngày Phục Sinh.", "Tìm kiếm danh dự ở Đời Sau."),
        "dua_q_israfana" to DuaText("Tha thứ cho sự thái quá của chúng tôi", "Lạy Chúa, xin tha thứ cho tội lỗi và sự thái quá của chúng con trong công việc, xin giúp chúng con vững vàng và giúp chúng con chống lại những kẻ không tin.", "Dua của những người bạn đồng hành của các Nhà tiên tri trước đó.", "Một dua cho sự kiên định và tha thứ."),
        "dua_q_jamiun_nas" to DuaText("Bạn sẽ tập hợp nhân loại", "Lạy Chúa, chắc chắn Ngài sẽ quy tụ nhân loại vào một Ngày mà không còn nghi ngờ gì nữa. Quả thật, Allah không vi phạm lời hứa của Ngài.", "Khẳng định sự chắc chắn vào Ngày Phục Sinh.", "Dua của những người có nền tảng kiến ​​thức vững chắc."),
        "dua_q_maash_shahidin" to DuaText("Viết cho chúng tôi trong số các nhân chứng", "Lạy Chúa, chúng tôi đã tin, xin ghi tên chúng tôi vào số những người làm chứng.", "Du mục của những người nhận ra sự thật và tin tưởng.", "Một dua cho việc chấp nhận đức tin của một người."),
        "dua_q_la_tajalna_zalimin" to DuaText("Không với những người làm sai", "Lạy Chúa, xin đừng đặt chúng con chung với những kẻ làm điều sai trái.", "Dua của người dân al-A'raf.", "Trốn tránh số phận kẻ làm ác."),
        "dua_q_tawaffana_muslimin" to DuaText("Kiên nhẫn và cái chết như người Hồi giáo", "Lạy Chúa, xin hãy đổ sự kiên nhẫn lên chúng con và khiến chúng con phải chết như những người Hồi giáo.", "Dua của các pháp sư của Pharaoh khi họ tin tưởng.", "Kiên nhẫn trong thử thách và kết thúc bằng đức tin."),
        "dua_q_la_tajalna_fitnah" to DuaText("Không phải là phiên tòa dành cho những kẻ áp bức", "Chúng tôi trông cậy vào Allah. Lạy Chúa, xin đừng biến chúng con thành thử thách cho những kẻ làm điều sai trái, và xin hãy cứu chúng con bằng lòng thương xót của Ngài khỏi những kẻ không tin.", "Dua của người dân Musa (AS).", "Một dua để giải cứu khỏi sự áp bức và áp bức."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Dua of Nuh (AS) cho sự tha thứ", "Lạy Chúa, con xin nương náu nơi Ngài để không xin Ngài điều gì mà con không biết. Và trừ khi Chúa tha thứ và thương xót con, con sẽ ở trong số những kẻ thua cuộc.", "Sự ăn năn của Tiên tri Nuh (AS).", "Một bài học về cách hỏi đúng cách."),
        "dua_q_mudkhala_sidq" to DuaText("Lối vào và lối ra của sự thật", "Lạy Chúa, xin cho con đi vào bằng lẽ thật và ra đi bằng lẽ thật, và xin ban cho con quyền năng hỗ trợ.", "Trước khi vào một nhiệm vụ, nhà hoặc địa điểm mới.", "Dua đã dạy cho Nhà tiên tri ﷺ vào thời điểm Hijrah."),
        "dua_q_la_tadharni_fardan" to DuaText("Dua của Zakariya (AS) - Đừng để tôi một mình", "Lạy Chúa, xin đừng bỏ con một mình, và Ngài là người thừa kế tốt nhất.", "Dành cho những người đang tìm kiếm trẻ em.", "Thông qua dua này Allah đã cấp cho Yahya (AS)."),
        "dua_q_munzalan_mubarakan" to DuaText("Một bến đỗ may mắn", "Lạy Chúa, xin cho con hạ cánh ở một bến đỗ may mắn, và Ngài là người tốt nhất trong số những người đưa con vào đất liền.", "Khi chuyển đến nhà mới hoặc dừng chân ở đâu đó — dua của Nuh (AS).", "Một dua để cầu phúc ở một nơi mới."),
        "dua_q_amanna_faghfir" to DuaText("Chúng tôi tin, nên hãy tha thứ cho chúng tôi", "Lạy Chúa, chúng con đã tin, xin hãy tha thứ và thương xót chúng con, và Chúa là Đấng có lòng thương xót tốt nhất.", "Dua của những người hầu công chính của Allah.", "Một bản du ca toàn diện cho sự tha thứ và lòng thương xót."),
        "dua_q_isrif_jahannam" to DuaText("Ngăn chặn sự trừng phạt của địa ngục", "Lạy Chúa, xin tránh cho chúng con hình phạt của Địa ngục; quả thực sự trừng phạt của nó luôn đeo bám. Quả thực, đó là một nơi định cư và cư trú tà ác.", "Dua của những người hầu của Đấng Nhân từ nhất ('Ibad ar-Rahman).", "Một dua Kinh Qur'an để ẩn náu khỏi Địa ngục."),
        "dua_q_hab_li_hukman" to DuaText("Dua của Ibrahim (AS) — Trí tuệ và Jannah", "Lạy Chúa, xin hãy ban cho con sự khôn ngoan và kết hợp với con với những người công chính, ban cho con một danh hiệu cao quý trong các thế hệ sau, và biến con thành một trong những người thừa kế của Khu vườn Hạnh phúc.", "Cầu xin sự khôn ngoan, bầu bạn của người công chính và Thiên đường.", "Một bản dua toàn diện của Ibrahim (AS)."),
        "dua_q_lut_najjini_ahli" to DuaText("Dua Lut (AS) — Cứu Gia Đình Tôi", "Lạy Chúa, xin hãy cứu con và gia đình con khỏi (hậu quả) những gì họ đã làm.", "Bảo vệ gia đình mình khỏi môi trường tà ác.", "Bảo vệ gia đình khỏi cái ác."),
        "dua_q_sulaiman_awzini" to DuaText("Dua của Sulaiman (AS) cho lòng biết ơn", "Lạy Chúa, xin cho con biết ơn Chúa vì ân huệ Chúa đã ban cho con và cha mẹ con, và làm những việc công chính đẹp lòng Chúa, và chấp nhận con bởi lòng thương xót của Chúa giữa những tôi tớ công chính của Chúa.", "Về khả năng biết ơn những phước lành.", "Lời tri ân của Sulayman (AS)."),
        "dua_q_musa_zalamtu" to DuaText("Dua of Musa (AS) — Tôi đã sai lầm chính mình", "Lạy Chúa, con đã sai lầm, xin hãy tha thứ cho con.", "Sự ăn năn ngay lập tức sau một sai lầm.", "Allah đã tha thứ cho Musa (AS)."),
        "dua_q_musa_najjini" to DuaText("Dua of Musa (AS) — Cứu tôi khỏi những kẻ áp bức", "Lạy Chúa, xin cứu con khỏi những người làm điều sai trái.", "Khi sợ hãi những kẻ áp bức.", "Dua của Musa (AS) khi rời khỏi Ai Cập."),
        "dua_q_lut_unsurni" to DuaText("Dua of Lut (AS) — Giúp chống lại những kẻ tham nhũng", "Lạy Chúa, xin giúp con chống lại những kẻ tham nhũng.", "Để được giúp đỡ chống lại những kẻ gieo rắc tham nhũng.", "Dua của những người đứng vững trên sự thật."),
        "dua_q_hab_li_salihin" to DuaText("Dua của Ibrahim (AS) vì một đứa trẻ chính trực", "Lạy Chúa, xin ban cho con (một đứa trẻ) trong số những người công chính.", "Đòi con cái đàng hoàng.", "Thông qua dua này, Isma'il (AS) đã được cấp."),
        "dua_q_wasita_kulla_shay" to DuaText("Dua của các thiên thần mang ngai vàng", "Lạy Chúa, Chúa bao trùm vạn vật trong lòng thương xót và hiểu biết, xin hãy tha thứ cho những ai ăn năn và đi theo đường lối của Ngài, đồng thời bảo vệ họ khỏi hình phạt của Địa ngục.", "Các thiên thần ngự trên ngai vàng thực hiện điều này cho các tín đồ.", "Được đọc với mục đích được đưa vào dua của các thiên thần."),
        "dua_q_ikhwanina" to DuaText("Dành cho những người anh em đi trước chúng ta", "Lạy Chúa, xin tha thứ cho chúng con và anh em chúng con, những người đã có đức tin trước chúng con, và xin đừng để trong lòng chúng con có sự oán giận đối với những người có đức tin. Lạy Chúa chúng con, Ngài quả thật là Đấng Nhân Lành và Đầy Lòng Thương Xót.", "Một dua dành cho những tín đồ đến trước và vì một trái tim trong sạch.", "Một dua dành cho những người bạn đồng hành cao quý (RA) và những tín đồ trước đó."),
        "dua_q_alayka_tawakkalna" to DuaText("Chúng tôi tin cậy vào bạn (Ibrahim AS)", "Lạy Chúa, chúng con trông cậy vào Ngài, chúng con hướng về Ngài và hướng về Ngài là sự trở lại. Lạy Chúa, xin đừng biến chúng con thành thử thách cho những kẻ không tin và hãy tha thứ cho chúng con. Lạy Chúa chúng con, Ngài quả thực là Đấng Toàn Năng, Đấng Thông Thái.", "Dua của Ibrahim (AS) và những người bạn đồng hành của anh ấy.", "Một sự phụ thuộc vào Allah và hướng về Ngài."),
        "dua_q_atmim_nurana" to DuaText("Hoàn thiện ánh sáng của chúng tôi", "Lạy Chúa, xin ban ánh sáng hoàn hảo cho chúng con và tha thứ cho chúng con. Quả thật, Ngài có quyền trên mọi sự.", "Dua của các tín đồ vào Ngày Phục Sinh.", "Yêu cầu ánh sáng trên Sirat."),
        "dua_q_asiya_baytan" to DuaText("Dua của Asiya - Một ngôi nhà ở Jannah", "Lạy Chúa, xin hãy xây cho con gần Ngài một ngôi nhà trên Thiên đường, cứu con khỏi Pha-ra-ôn và những việc làm của hắn, cũng như cứu con khỏi những kẻ làm điều sai trái.", "Dua của Asiya, vợ của Pharaoh.", "Allah đã biến cô ấy thành một tấm gương cho các tín đồ."),
        "dua_adhan_response" to DuaText("Trả lời Adhan", "Không có sức mạnh và quyền lực nào ngoại trừ Allah.", "Lặp lại những gì muezzin nói; tại 'Hayya 'alas-salah' và 'Hayya 'alal-falah' nói điều này.", "Ai đáp lại từ trái tim sẽ được vào Thiên đường."),
        "dua_adhan_shahadah" to DuaText("Sau Shahadah của Muazzin", "Và tôi cũng làm chứng rằng không ai có quyền được tôn thờ ngoại trừ Allah, một mình, không có đối tác, và rằng Muhammad ﷺ là người hầu và Sứ giả của Ngài. Tôi hài lòng với Allah là Chúa, với Muhammad ﷺ là Sứ giả và với Hồi giáo là tôn giáo.", "Khi nghe lời chứng về đức tin của muezzin.", "Tội lỗi của ông được tha thứ."),
        "dua_istiftah_baid" to DuaText("Mở đầu Dua: Khoảng cách với tôi khỏi tội lỗi", "Lạy Allah, xin hãy tránh xa tội lỗi của con như Ngài đã cách xa phương đông khỏi phương tây. Ôi Allah, hãy rửa sạch tội lỗi cho tôi như chiếc áo trắng được giặt sạch bụi bẩn. Ôi Allah, hãy rửa sạch tội lỗi của tôi bằng nước, tuyết và mưa đá.", "Sau phần mở đầu takbir (cũng có thể nói thay cho Sana).", "Nhà tiên tri ﷺ đã đọc điều này giữa takbir và buổi đọc kinh."),
        "dua_hamdan_kathiran" to DuaText("Lời khen ngợi dồi dào sau Ruku", "Lạy Chúa chúng con, Chúa đáng được ngợi khen – lời khen ngợi dồi dào, tinh tuyền và phúc lành.", "Sau khi trỗi dậy từ ruku, cùng với 'Rabbana lakal-hamd'.", "Hơn ba mươi thiên thần đang chạy đua để trở thành người đầu tiên ghi lại nó."),
    )
}
